import{z as B,x as A,o as E,c as p,q as n,j as i,D as e,d as o,s as l,S as r,b as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"会话管理","description":"","frontmatter":{"title":"会话管理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/session-management.md","filePath":"cs/session-management.md","lastUpdated":1791413859000}'),d={name:"cs/session-management.md"};function D(m,a,c,h,u,S){const s=A("Mermaid");return E(),p("div",null,[a[2]||(a[2]=n('<h1 id="会话管理" tabindex="-1">会话管理 <a class="header-anchor" href="#会话管理" aria-label="Permalink to &quot;会话管理&quot;">​</a></h1><div class="epigraph"><p>会话把「已认证」记在服务器或绑定在 cookie 上。标识要不可猜、要随权限变化而更新、要能作废。Secure、HttpOnly、SameSite 是浏览器合同，不是装饰性旗标。</p><footer>—— 据 RFC 6265；OWASP 会话管理；对照 Felten 等对 cookie 的早期讨论</footer></div><p>上一课<a href="/cs/jwt-pitfalls">JWT</a>给了一种无状态形状。缺口是<strong>有状态会话仍是默认</strong>：会话 ID、固定、CSRF、超时。不重写 CSRF 课的全部，只把会话生命周期钉进身份单元。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>登录后若不换会话 ID，固定攻击把预种 ID 升级成认证会话——只陈述性质。cookie 缺 Secure 则明文泄漏；缺 HttpOnly 则 XSS 可偷。缺口是生命周期与旗标，不是再讲表单。</p><h3 id="登出必须作废服务端" tabindex="-1">登出必须作废服务端 <a class="header-anchor" href="#登出必须作废服务端" aria-label="Permalink to &quot;登出必须作废服务端&quot;">​</a></h3><p>删浏览器 cookie 而服务端仍认 ID，等于没登出。</p><p><span class="marginnote">RFC 6265。SameSite 缓解部分 CSRF，不是全部。本课不给窃取 cookie 的步骤。</span></p><p><span class="marginnote">术语翻译：「会话固定」就是攻击者先把一个自己知道的会话 ID 种进你的浏览器，等你登录后这个 ID 被升级成认证会话——他拿同一个 ID 就进了门。防御正对应「认证成功即轮换 ID」这一步。</span></p><p><span class="marginnote">直觉类比：三个旗标像给 cookie 上三把锁——Secure 只走加密通道（防路上被抄）、HttpOnly 不让脚本读（防 XSS 撬锁）、SameSite 跨站请求不带（防 CSRF 冒名）。少一把锁，就多一条被偷的路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：认证成功→换 ID→设旗标→绝对与空闲超时→吊销。对照 JWT 访问令牌+刷新。多设备会话要能列与踢。</p>',13)),(E(),i(r,null,{default:e(()=>[l(s,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOGIN%5B%22%E8%AE%A4%E8%AF%81%E6%88%90%E5%8A%9F%22%5D%20--%3E%20ROT%5B%22%E8%BD%AE%E6%8D%A2%E4%BC%9A%E8%AF%9D%20ID%22%5D%0A%20%20ROT%20--%3E%20FLAG%5B%22Secure%20HttpOnly%20SameSite%22%5D%0A%20%20FLAG%20--%3E%20TTL%5B%22%E8%B6%85%E6%97%B6%E4%B8%8E%E5%90%8A%E9%94%80%22%5D%0A%20%20TTL%20--%3E%20OUT%5B%22%E7%99%BB%E5%87%BA%E4%BD%9C%E5%BA%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"身份是时间上的状态机。OAuth 下一课把这台机器拆成授权码、重定向与客户端类型——会话仍要，只是多了第三方。",-1)),a[5]||(a[5]=t("p",null,"上面那张图是登录到登出的合同清单；下面这张把「时间上的状态机」展开——空闲超时与绝对超时各自在哪个判断点把会话掐掉。",-1)),(E(),i(r,null,{default:e(()=>[l(s,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%BC%9A%E8%AF%9D%E6%9C%89%E6%95%88%22%5D%20--%3E%20B%7B%22%E6%9C%89%E6%B4%BB%E5%8A%A8%3F%22%7D%0A%20%20B%20--%20%22%E5%90%A6%20%E8%B6%85%E8%BF%87%E7%A9%BA%E9%97%B2%E4%B8%8A%E9%99%90%22%20--%3E%20C%5B%22%E7%A9%BA%E9%97%B2%E8%B6%85%E6%97%B6%20%E5%A4%B1%E6%95%88%22%5D%0A%20%20B%20--%20%22%E6%98%AF%22%20--%3E%20D%7B%22%E8%B7%9D%E7%99%BB%E5%BD%95%E8%B6%85%E8%BF%87%E7%BB%9D%E5%AF%B9%E4%B8%8A%E9%99%90%3F%22%7D%0A%20%20D%20--%20%22%E6%98%AF%22%20--%3E%20E%5B%22%E7%BB%9D%E5%AF%B9%E8%B6%85%E6%97%B6%20%E5%BC%BA%E5%88%B6%E9%87%8D%E7%99%BB%22%5D%0A%20%20D%20--%20%22%E5%90%A6%22%20--%3E%20F%5B%22%E7%BB%AD%E6%9C%9F%20%E7%BB%A7%E7%BB%AD%E6%9C%89%E6%95%88%22%5D%0A%20%20C%20--%3E%20G%5B%22%E6%9C%8D%E5%8A%A1%E7%AB%AF%E5%88%A0%E8%AE%B0%E5%BD%95%20%E6%B5%8F%E8%A7%88%E5%99%A8%E6%B8%85%20cookie%22%5D%0A%20%20E%20--%3E%20G%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">数字实例：空闲超时 30 分钟、绝对超时 12 小时是常见搭配。挂页面去吃饭 40 分钟回来要重登（空闲超时触发）；就算一直在操作，到第 12 小时也被强制重登——绝对超时挡的是「被无限续期的活会话」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部 cookie 前缀写完。OAuth 攻击面下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>JWT 无状态；会话 ID 有状态，要轮换与作废。</li><li>旗标与超时是合同；登出在服务端。</li><li>固定会话是认证前 ID 被绑上用户。</li><li>下一课 OAuth 攻击面。</li><li>出处：RFC 6265；OWASP Session Management；对照 RFC 6819。</li></ul>',5))])}const f=B(d,[["render",D]]);export{T as __pageData,f as default};
